contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 loanID, address to) public {
        require(loanID < 8);
        require(to != address(0));

        address approvalsBefore = c.approvals(loanID); if (__ESBMC_reverted()) return;

        bool reverted;
        c.approveTransfer(to, loanID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.approvals(loanID) == approvalsBefore);
    }

    receive() external payable {}
}

