pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 loanID, address to) internal {
        loanID = bound(loanID, 0, 7);
        vm.assume(to != address(0));
        address approvalsBefore;
        try c.approvals(loanID) returns (address __r) { approvalsBefore = __r; } catch { return; }
        bool reverted;
        try c.approveTransfer(to, loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.approvals(loanID) == approvalsBefore);
    }

    function testFuzz_run(uint256 loanID, address to) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(loanID, to);
    }

    receive() external payable {}
}
